'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const escapeHTML = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',agent:'M12 3v3M3 12h3m12 0h3M12 18v3M8 8h8v8H8ZM5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',calendar:'M5 5h14v15H5ZM8 3v4m8-4v4M5 10h14m-10 4h2m2 0h2m-6 3h2',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8m6 10v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',chat:'M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0ZM7 10h10M7 14h6',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',chart:'M4 3v17h17M8 16v-5m5 5V7m5 9V4',user:'M20 21v-2a7 7 0 0 0-14 0v2M17 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',about:'M12 8v.1m0 4v5M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',arrow:'M5 12h14m-5-5 5 5-5 5',logout:'M9 4H4v16h5m6-13 5 5-5 5m-5-5h10',download:'M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6',check:'m5 12 4 4L19 6'};
const icon=(name,cls='')=>`<svg class="${cls}" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.heart}"/></svg>`;
const brand=()=>'<div class="brand"><span class="brand-symbol">+</span><span>iCure</span></div>';
const state={user:null,csrf:'',route:'dashboard',tab:'login',onlineConfigured:false,agentHistory:[],latest:null,contacts:[],peer:null,poll:null,lang:'zh',draft:null};
const dep={Cardiology:'心内科',Dermatology:'皮肤科',Pediatrics:'儿科',Ophthalmology:'眼科',ENT:'耳鼻喉科',Obstetrics:'妇产科','未分类':'未分类'};
const depLabel=x=>dep[x]||x;
const roleName=()=>state.user?.role==='doctor'?'医生':'患者';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const tomorrow=()=>{const d=new Date(Date.now()+86400000);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);};
const formatDate=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'';
const avatar=(profile,extra='')=>`<img class="avatar ${extra}" src="${e(profile?.avatar||'/assets/icon1.png')}" alt="头像">`;
const badge=(label,type='')=>`<span class="badge ${type}">${e(label)}</span>`;
const statusLabel=x=>({booked:'已预约',cancelled:'已取消',Ongoing:'治疗中',Completed:'已完成',Recovered:'已康复'}[x]||x);
const empty=(message='暂无记录')=>`<div class="empty">${icon('calendar')}<div>${e(message)}</div></div>`;
let toastTimer;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
async function api(path,data){
  const options={headers:{},credentials:'same-origin'};
  if(data!==undefined){options.method='POST';options.headers={'Content-Type':'application/json','X-CSRF-Token':state.csrf};options.body=JSON.stringify(data);}
  const response=await fetch(path,options);const body=await response.json();
  if(!response.ok){if(response.status===401&&state.user){state.user=null;clearInterval(state.poll);renderLogin();}throw Error(body.error||'请求失败');}
  return body;
}
function showError(error,el){if(el){el.textContent=error.message;el.classList.remove('hidden');}else toast(error.message);}
function field(label,name,value='',type='text',attrs=''){return `<label class="field">${e(label)}<input name="${name}" type="${type}" value="${e(value)}" ${attrs}></label>`;}
function departmentOptions(selected='',all=false){return (all?'<option value="">全部科室</option>':'')+Object.entries(dep).map(([k,v])=>`<option value="${e(k)}" ${k===selected?'selected':''}>${e(v)}</option>`).join('');}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">YOUR HEALTH, OUR PRIORITY</div><h1>${e(title)}</h1><p>${e(subtitle)}</p></div>${action}</div>`;}
function download(name,data,type='text/plain;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function modal(html){const el=$('#modal');el.innerHTML=`<button class="close" data-action="close-modal" aria-label="关闭">×</button>${html}`;if(!el.open)el.showModal();}

function renderLogin(){
  clearInterval(state.poll);state.poll=null;
  const register=state.tab==='register';
  $('#app').innerHTML=`<div class="login-page"><section class="login-story">${brand()}<div class="eyebrow">CONNECTED CARE, CLOSE TO YOU</div><h1>让健康管理，<br>回归简单。</h1><p>从每一次问候，到下一次预约。<br>为医生与患者连接更清晰的就医旅程。</p><img class="login-photo" src="/assets/hospital.jpg" alt="原项目医院照片"><div class="small">iCure 智慧医疗管理系统 · Windows 本机版</div></section><section class="login-form-side"><div class="login-box"><div class="mobile-brand">${brand()}</div><div class="eyebrow">WELCOME TO ICURE</div><h2>${register?'创建你的账号':'欢迎回来'}</h2><p>${register?'选择身份，开始管理你的健康旅程。':'登录工作台，继续你的健康旅程。'}</p><div class="login-tabs"><button data-action="login-tab" data-tab="login" class="${!register?'active':''}">登录</button><button data-action="login-tab" data-tab="register" class="${register?'active':''}">注册</button></div><form id="auth-form"><div class="error hidden" id="auth-error" role="alert"></div>${field('用户名','username','','text','required maxlength="80" autocomplete="username"')}${field('密码','password','','password',`required maxlength="256" autocomplete="${register?'new-password':'current-password'}" ${register?'minlength="6"':''}`)}${register?`${field('姓名','name','','text','required maxlength="80"')}<div class="form-grid"><label class="field">身份<select name="role" id="register-role"><option value="patient">患者</option><option value="doctor">医生</option></select></label>${field('年龄（可选）','age','','number','min="0" max="120" step="1"')}</div><label class="field hidden" id="register-department">科室<select name="department">${departmentOptions('ENT')}</select></label>${field('联系电话（可选）','telephone','','tel','maxlength="40"')}`:''}<button class="primary" type="submit">${register?'注册并进入':'登录工作台'} ${icon('arrow')}</button></form>${!register?'<div class="divider"></div><div class="small muted">先体验一下？以下为虚构演示账号</div><div class="demo-buttons"><button class="secondary" data-action="demo-login" data-role="patient">患者演示</button><button class="secondary" data-action="demo-login" data-role="doctor">医生演示</button></div>':''}<p class="footer-note">原有账号密码仍可使用。数据保存在本机；AI 默认使用离线规则，启用在线模型前会要求你明确选择发送。</p></div></section></div>`;
  $('#auth-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const data=Object.fromEntries(new FormData(form));const button=$('button[type=submit]',form);button.disabled=true;try{await login(data,register);}catch(error){showError(error,$('#auth-error'));}finally{button.disabled=false;}});
  $('#register-role')?.addEventListener('change',event=>$('#register-department').classList.toggle('hidden',event.target.value!=='doctor'));
}
async function login(data,register=false){const result=await api(register?'/api/register':'/api/login',data);state.user=result.user;state.csrf=result.csrf;state.onlineConfigured=false;state.route='dashboard';state.latest=null;await renderShell();}
const navigation=()=>[
 ['dashboard','home','健康概览','Overview'],['agent','agent','医疗 Agent','Care Agent'],['appointments','calendar','预约管理','Appointments'],
 ...(state.user.role==='doctor'?[['patients','people','患者管理','Patients'],['stats','chart','数据统计','Statistics']]:[['records','people','诊疗记录','Care records'],['health','heart','健康评估','Health log']]),
 ['chat','chat','医患沟通','Messages'],['profile','user','个人资料','Profile'],['about','about','关于 iCure','About iCure']
];
async function renderShell(){
  const nav=navigation();const p=state.user.profile;
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="主导航">${nav.map(([id,i,zh,en])=>`<button data-route="${id}" class="${id===state.route?'active':''}">${icon(i)}<span>${state.lang==='zh'?zh:en}</span>${id==='agent'?'<span class="new">NEW</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-note"><span class="dot"></span>本机服务已连接<br>数据留在你的电脑<br>离线也能管理健康</div><div class="user">${avatar(p)}<div><p title="${e(p.name)}">${e(p.name)}</p><small class="muted">${roleName()}工作台</small></div><button data-action="logout" title="退出登录" aria-label="退出登录">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">iCure &nbsp; / &nbsp; <strong id="breadcrumb"></strong></div><div class="top-actions"><span class="date">${new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric',weekday:'long'})}</span><button class="lang-button" data-action="language">${state.lang==='zh'?'EN':'中文'}</button><span class="role-badge">${roleName()}端</span><button data-action="logout" title="退出登录" aria-label="退出登录">${icon('logout')}</button></div></header><div class="content" id="content"></div></main></div>`;
  await renderRoute();
}
async function go(route){if(!state.user)return;state.route=route;$$('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route));await renderRoute();}
async function renderRoute(){
  clearInterval(state.poll);state.poll=null;
  const route=state.route;
  const item=navigation().find(x=>x[0]===route);$('#breadcrumb').textContent=item?.[state.lang==='zh'?2:3]||'';
  const content=$('#content');content.innerHTML='<div class="loading">正在加载…</div>';
  try{switch(route){case'dashboard':await renderDashboard();break;case'agent':await renderAgent();break;case'appointments':await renderAppointments();break;case'patients':await renderPatients();break;case'records':await renderRecords();break;case'health':await renderHealth();break;case'chat':await renderChat();break;case'profile':renderProfile();break;case'stats':await renderStats();break;case'about':await renderAbout();break;default:await renderDashboard();}}catch(error){if(state.route===route&&state.user)content.innerHTML=`<div class="error" role="alert">${e(error.message)}</div><button class="secondary section-gap" data-action="retry">重新加载</button>`;}
}
function appointmentTable(items,limit){const list=limit?items.slice(0,limit):items;return list.length?`<div class="table-scroll"><table><thead><tr><th>${state.user.role==='doctor'?'患者':'医生 / 科室'}</th><th>预约日期</th><th>时刻</th><th>状态</th><th>操作</th></tr></thead><tbody>${list.map(a=>`<tr><td><div class="cell-name">${e(state.user.role==='doctor'?a.patient_name:a.doctor_name)}</div><small class="muted">${e(state.user.role==='doctor'?a.telephone:depLabel(a.department))}</small></td><td>${a.date?e(a.date):badge('日期待核实','warn')}</td><td>${e(a.time)}</td><td>${badge(statusLabel(a.status),a.status==='cancelled'?'warn':'')}</td><td>${a.status==='booked'?`<button class="text-button" data-action="cancel-appointment" data-id="${a.id}">取消预约</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有预约，先选择医生或让 Agent 帮你整理就诊需求。');}
async function renderDashboard(){
 const d=await api('/api/dashboard');if(state.route!=='dashboard')return;
 const booked=d.appointments.filter(a=>a.status==='booked'&&a.date&&a.date>=d.today);const doctor=state.user.role==='doctor';
 const relationCount=doctor?new Set(d.relations.map(r=>r.patient_id)).size:d.relations.length;
 $('#content').innerHTML=heading(`你好，${state.user.profile.name}。`,'每一步关怀，都从了解你的健康开始。',`<button class="secondary" data-route="profile">${icon('user')} 管理个人资料</button>`)+`<section class="hero"><div><div class="eyebrow">YOUR PERSONAL CARE COMPANION</div><h2>有疑问，先和医疗 Agent 聊聊。</h2><p>描述你的需求，让助手整理就诊摘要、查找医生和准备预约。每一步清晰可见，每一次预约由你确认。</p><button class="primary" data-route="agent">${icon('agent')} 开始对话 ${icon('arrow')}</button></div><div class="hero-art"><svg viewBox="0 0 200 160" fill="none" aria-hidden="true"><circle cx="110" cy="80" r="70" fill="#d5e3cc"/><rect x="55" y="23" width="96" height="120" rx="14" fill="#fff" stroke="#98b492"/><path d="M89 45h30m-30 13h42M75 87h17l8-18 12 34 9-17h15" stroke="#5d947b" stroke-width="3" stroke-linecap="round"/><circle cx="155" cy="114" r="25" fill="#187962"/><path d="M155 101v26m-13-13h26" stroke="#fff" stroke-width="4" stroke-linecap="round"/><circle cx="43" cy="55" r="13" fill="#abc49f"/><path d="m38 55 4 4 7-8" stroke="#fff" stroke-width="2"/></svg></div></section><div class="grid3"><div class="card metric"><div class="flex spread"><span class="metric-label">${doctor?'待处理预约':'即将到来的预约'}</span><span class="metric-icon">${icon('calendar')}</span></div><div class="metric-value">${booked.length}<small> 次</small></div><small>已确认日期的有效预约</small></div><div class="card metric"><div class="flex spread"><span class="metric-label">${doctor?'关联患者':'我的诊疗记录'}</span><span class="metric-icon">${icon('people')}</span></div><div class="metric-value">${relationCount}<small> ${doctor?'位':'条'}</small></div><small>${doctor?'仅显示与你关联的患者':'医生记录，随时查阅'}</small></div><div class="card metric"><div class="flex spread"><span class="metric-label">${doctor?'今日预约':'最近一次 BMI'}</span><span class="metric-icon">${icon('heart')}</span></div><div class="metric-value">${doctor?booked.filter(a=>a.date===d.today).length:(d.health[0]?.bmi??'—')}</div><small>${doctor?'以北京时间计算':d.health[0]?'记录于 '+formatDate(d.health[0].created):'记录身高体重，了解变化'}</small></div></div><div class="grid2 section-gap"><section class="card"><div class="card-head"><h2>近期预约</h2><button class="text-button" data-route="appointments">查看全部 →</button></div>${appointmentTable(booked,4)}</section><section class="card"><div class="card-head"><h2>${doctor?'患者近况':'照护小记'}</h2>${badge('持续关注')}</div>${d.relations.length?d.relations.slice(0,3).map(r=>`<div class="record-item section-gap"><div class="flex spread"><strong class="small">${e(doctor?r.name:r.doctor_name)}</strong>${badge(statusLabel(r.status))}</div><p class="muted preserve">${e((r.symptoms||'尚未填写主诉').slice(0,160))}</p></div>`).join(''):empty('诊疗记录会在建立医患关系后显示。')}<button class="text-button section-gap" data-route="${doctor?'patients':'health'}">${doctor?'管理患者记录':'记录今天的健康数据'} →</button></section></div>`;
}
async function renderAppointments(){
 const [items,doctors]=await Promise.all([api('/api/appointments'),api('/api/doctors')]);if(state.route!=='appointments')return;
 $('#content').innerHTML=heading('预约管理','选择合适的医生，让下一次就诊更从容。',state.user.role==='patient'?'<button class="primary" data-action="book-modal">＋ 新建预约</button>':'')+`<section class="card"><div class="card-head"><h2>我的预约</h2>${badge(items.length+' 条记录')}</div>${appointmentTable(items)}</section>`+(state.user.role==='patient'?`<section class="card section-gap"><div class="card-head"><h2>医生目录</h2><span class="muted small">来自原项目与本机新注册档案</span></div><div class="filter-row"><input id="doctor-search" aria-label="搜索医生姓名" placeholder="搜索医生姓名"><select id="doctor-department" aria-label="筛选科室">${departmentOptions('',true)}</select></div><div class="grid3" id="doctor-list"></div></section>`:'');
 if(state.user.role==='patient'){
  const paint=()=>{const search=$('#doctor-search').value.toLowerCase();const department=$('#doctor-department').value;const filtered=doctors.filter(d=>(!department||d.department===department)&&d.name.toLowerCase().includes(search));$('#doctor-list').innerHTML=filtered.length?filtered.map(d=>`<article class="doctor-card"><div class="flex">${avatar(d)}<div><h3>${e(d.name)}</h3><p>${e(depLabel(d.department))}</p></div></div><button class="primary" data-action="book-modal" data-doctor="${d.id}">选择医生</button></article>`).join(''):empty('没有符合条件的医生。');};$('#doctor-search').addEventListener('input',paint);$('#doctor-department').addEventListener('change',paint);paint();
 }
}
async function bookModal(did='',draft=null){
 const doctors=await api('/api/doctors');const date=draft?.date||tomorrow();
 modal(`<h2>确认预约信息</h2><p class="muted small">核对后点击确认才会预约。${draft?'本次摘要会作为首次关联时的主诉交给医生。':''}</p><form id="booking-form"><div class="error hidden" role="alert"></div><div class="form-grid"><label class="field full">医生<select name="doctor_id" id="book-doctor" required><option value="">请选择医生</option>${doctors.map(d=>`<option value="${d.id}" ${String(d.id)===String(did)?'selected':''}>${e(d.name)} · ${e(depLabel(d.department))}</option>`).join('')}</select></label>${field('预约日期','date',date,'date',`required min="${today()}"`)}<label class="field">预约时刻<select name="time" id="book-time" required><option value="">请先选择医生和日期</option></select></label>${draft?`<label class="field full">就诊摘要（可修改）<textarea name="summary" maxlength="6000">${e(draft.summary)}</textarea></label>`:''}</div><div class="notice section-gap">这是本项目的本机预约数据，不代表真实医院已挂号。号源会在提交时再次核验。</div><div class="flex section-gap"><button class="primary" type="submit">确认预约</button><button class="secondary" type="button" data-action="close-modal">返回修改</button></div></form>`);
 let slotsRequest=0;
 const slots=async()=>{const request=++slotsRequest;const doctor=$('#book-doctor').value;const day=$('[name=date]',$('#booking-form')).value;const target=$('#book-time');if(!doctor||!day)return;target.innerHTML='<option value="">正在查询…</option>';try{const list=await api(`/api/slots?doctor_id=${encodeURIComponent(doctor)}&date=${encodeURIComponent(day)}`);if(request!==slotsRequest||!target.isConnected)return;target.innerHTML='<option value="">请选择时刻</option>'+list.map(s=>`<option value="${s.time}" ${s.available?'':'disabled'}>${s.time}${s.available?'':' · 不可约'}</option>`).join('');}catch(error){showError(error,$('.error',$('#booking-form')));}};
 $('#book-doctor').addEventListener('change',slots);$('[name=date]',$('#booking-form')).addEventListener('change',slots);if(did)await slots();
 $('#booking-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const button=$('[type=submit]',form);button.disabled=true;try{await api('/api/appointments/book',Object.fromEntries(new FormData(form)));$('#modal').close();toast('预约成功，已写入本机预约记录。');if(state.route==='appointments'||state.route==='dashboard')await renderRoute();}catch(error){showError(error,$('.error',form));}finally{button.disabled=false;}});
}
async function renderPatients(){
 const list=await api('/api/patients');if(state.route!=='patients')return;
 $('#content').innerHTML=heading('患者管理','记录主诉、诊疗建议和治疗进展。只显示与你关联的患者。')+`<section class="card"><div class="filter-row"><input id="patient-search" aria-label="搜索患者" placeholder="搜索患者姓名、症状"></div><div id="patient-list"></div></section>`;
 const paint=()=>{const value=$('#patient-search').value.toLowerCase();const filtered=list.filter(p=>(p.name+' '+p.symptoms).toLowerCase().includes(value));$('#patient-list').innerHTML=filtered.length?`<div class="table-scroll"><table><thead><tr><th>患者</th><th>年龄 / 性别</th><th>主诉</th><th>状态</th><th>操作</th></tr></thead><tbody>${filtered.map(p=>`<tr><td class="cell-name">${e(p.name)}</td><td>${e(p.age??'未填')} / ${e(p.gender||'未填')}</td><td>${e((p.symptoms||'待填写').slice(0,100))}</td><td>${badge(statusLabel(p.status))}</td><td><button class="text-button" data-edit-patient="${p.id}">查看 / 编辑</button></td></tr>`).join('')}</tbody></table></div>`:empty('没有匹配的关联患者。');$$('[data-edit-patient]').forEach(b=>b.addEventListener('click',()=>editPatient(list.find(p=>p.id===Number(b.dataset.editPatient)))));};$('#patient-search').addEventListener('input',paint);paint();
}
function editPatient(p){
 modal(`<h2>${e(p.name)} · 诊疗记录</h2><form id="patient-form"><div class="error hidden" role="alert"></div><input type="hidden" name="id" value="${p.id}"><div class="stack"><label class="field">主诉 / 症状<textarea name="symptoms" maxlength="6000">${e(p.symptoms)}</textarea></label><label class="field">医生建议<textarea name="advice" maxlength="6000">${e(p.advice)}</textarea></label><label class="field">处方 / 治疗记录<textarea name="prescription" maxlength="6000">${e(p.prescription)}</textarea></label><label class="field">治疗状态<select name="status">${['待就诊','治疗中','已完成','已康复','Ongoing','Completed','Recovered'].map(s=>`<option value="${s}" ${s===p.status?'selected':''}>${e(statusLabel(s))}</option>`).join('')}</select></label><button class="primary" type="submit">保存诊疗记录</button></div></form>`);
 $('#patient-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const button=$('[type=submit]',form);button.disabled=true;try{await api('/api/patients/update',Object.fromEntries(new FormData(form)));$('#modal').close();toast('诊疗记录已保存。');await renderPatients();}catch(error){showError(error,$('.error',form));}finally{button.disabled=false;}});
}
async function renderRecords(){const data=await api('/api/dashboard');if(state.route!=='records')return;$('#content').innerHTML=heading('我的诊疗记录','查看关联医生填写的诊疗信息。')+`<section class="record-list">${data.relations.length?data.relations.map(r=>`<article class="card"><div class="card-head"><div><h2>${e(r.doctor_name)}</h2><small class="muted">${e(depLabel(r.department))}</small></div>${badge(statusLabel(r.status))}</div><div class="grid2"><div><h3>主诉 / 症状</h3><p class="preserve small">${e(r.symptoms||'尚未填写')}</p><h3>医生建议</h3><p class="preserve small">${e(r.advice||'尚未填写')}</p></div><div><h3>处方 / 治疗记录</h3><p class="preserve small">${e(r.prescription||'尚未填写')}</p></div></div><small class="muted">更新时间：${e(formatDate(r.updated))}</small></article>`).join(''):empty('预约医生后会建立医患关联，医生可以填写诊疗记录。')}</section>`;}
async function renderHealth(){
 const history=await api('/api/health');if(state.route!=='health')return;
 $('#content').innerHTML=heading('健康评估与记录','记录真实测量值，观察变化；助手不生成缺乏依据的“健康总分”。')+`<div class="grid2"><section class="card"><div class="card-head"><h2>记录身体指标</h2>${icon('heart')}</div><form id="health-form"><div class="error hidden" role="alert"></div><div class="form-grid">${field('身高 / cm','height','','number','required min="50" max="250" step="0.1"')}${field('体重 / kg','weight','','number','required min="2" max="500" step="0.1"')}${field('静息心率 / 次每分（可选）','heart_rate','','number','min="20" max="250" step="1"')}${field('体脂率 / %（可选）','body_fat','','number','min="1" max="75" step="0.1"')}${field('原项目视力自测分 / 100（可选）','vision','','number','min="0" max="100" step="1"')}</div><p class="small muted section-gap">视力自测分仅作为个人记录，不等同于标准视力检查。</p><div class="flex"><button class="primary" type="submit">计算 BMI 并保存</button><button class="secondary" type="button" data-action="eye-chart">查看原项目视力图</button></div></form></section><section class="card"><h2>最近一次记录</h2><div id="health-result">${history.length?healthResult(history[0]):empty('记录身高与体重后，在这里查看 BMI。')}</div><div class="notice section-gap">BMI 不能独立诊断健康状况。儿童、孕期及高肌肉量人群需结合专业评估。本系统保留测量记录，不据此开药或打分。</div><a class="small" href="https://www.nhs.uk/health-assessment-tools/calculate-your-body-mass-index/calculate-bmi-for-adults" target="_blank" rel="noreferrer">参考：NHS 成人 BMI 说明 ↗</a></section></div><section class="card section-gap"><div class="card-head"><h2>健康记录历史</h2>${badge(history.length+' 条')}</div>${history.length?`<div class="table-scroll"><table><thead><tr><th>时间</th><th>身高</th><th>体重</th><th>BMI</th><th>心率</th><th>体脂率</th><th>视力自测分</th></tr></thead><tbody>${history.map(h=>`<tr><td>${e(formatDate(h.created))}</td><td>${h.height} cm</td><td>${h.weight} kg</td><td>${h.bmi}</td><td>${e(h.heart_rate??'—')}</td><td>${e(h.body_fat??'—')}</td><td>${e(h.vision??'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有健康记录。')}</section>`;
 $('#health-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const button=$('[type=submit]',form);button.disabled=true;try{const result=await api('/api/health/save',Object.fromEntries(new FormData(form)));toast('健康记录已保存，BMI：'+result.bmi);await renderHealth();}catch(error){showError(error,$('.error',form));}finally{button.disabled=false;}});
}
function healthResult(h){return `<div class="health-result"><div class="small muted">BODY MASS INDEX</div><div class="metric-value">${e(h.bmi)}</div><div class="small muted">身高 ${e(h.height)} cm · 体重 ${e(h.weight)} kg</div><small class="muted">${e(formatDate(h.created))}</small></div>`;}
function renderProfile(){
 const p=state.user.profile;const doctor=state.user.role==='doctor';
 $('#content').innerHTML=heading('个人资料','维护你的档案和登录信息。')+`<div class="grid2"><section class="card"><div class="flex spread"><div class="flex">${avatar(p)}<div><h3>${e(p.name)}</h3><small class="muted">${roleName()}账号 · ${e(state.user.username)}</small></div></div><label class="file-label">更换头像<input id="avatar-upload" type="file" accept="image/png,image/jpeg,image/gif" aria-label="上传头像"></label></div><div class="divider"></div><form id="profile-form"><div class="error hidden" role="alert"></div><div class="form-grid">${field('姓名','name',p.name,'text','required maxlength="80"')}${field('用户名','username',state.user.username,'text','required maxlength="80"')}${field('年龄','age',p.age,'number','min="0" max="120" step="1"')}${field('性别','gender',p.gender,'text','maxlength="30"')}${field('联系电话','telephone',p.telephone,'tel','maxlength="40"')}${doctor?`<label class="field">科室<select name="department">${departmentOptions(p.department)}</select></label>`:''}<label class="field full">地址<input name="address" value="${e(p.address)}" maxlength="300"></label></div><div class="divider"></div><h3>修改密码（可选）</h3><div class="form-grid">${field('当前密码','old_password','','password','autocomplete="current-password" maxlength="256"')}${field('新密码','new_password','','password','autocomplete="new-password" maxlength="256" minlength="6"')}</div><button class="primary section-gap" type="submit">保存资料</button></form></section><section class="stack"><div class="card"><h2>你的本机数据</h2><p class="small muted">账号、预约和健康数据保存在新文件夹的 data 目录。可以导出当前账号有权查看的记录。</p><button class="secondary" data-action="export">${icon('download')} 导出我的数据</button><p class="small muted section-gap">完整恢复备份：停止服务后，复制整个 iCure-Windows 文件夹，包含 data 和头像文件。</p></div><div class="card"><h2>AI 与隐私</h2><p class="small muted">默认离线。在线模型密钥仅保留在当前登录会话内，退出登录或停止服务后清除。启用在线发送时，所选服务会收到当前描述、最近对话和本次摘要。</p><button class="text-button" data-route="agent">前往医疗 Agent →</button></div></section></div>`;
 $('#profile-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const button=$('[type=submit]',form);button.disabled=true;try{state.user=await api('/api/profile',Object.fromEntries(new FormData(form)));toast('资料已更新。');await renderShell();}catch(error){showError(error,$('.error',form));}finally{button.disabled=false;}});
 $('#avatar-upload').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('头像不能超过 2 MB。');const result=await api('/api/avatar',{file:await fileBase64(file)});state.user.profile.avatar=result.avatar;toast('头像已更新。');await renderShell();}catch(error){toast(error.message);}});
}
async function renderAgent(){
 const history=await api('/api/agent/history');if(state.route!=='agent')return;
 state.agentHistory=history;state.latest=[...history].reverse().find(h=>h.payload)?.payload||null;
 $('#content').innerHTML=heading('医疗 Agent','从一段描述，到一份清晰的就诊计划。',`<div class="flex"><button class="secondary" data-action="agent-settings">模型设置</button><button class="text-button" data-action="agent-clear">清空对话</button></div>`)+`<div class="agent-layout"><section class="card agent-main"><header class="agent-banner"><div><h2 class="flex">${icon('agent')} iCure 健康助手</h2><p>整理需求 · 连接医生 · 辅助预约</p></div><div class="agent-status"><span class="dot"></span><span id="agent-mode">${state.onlineConfigured?'在线模型已配置':'离线规则可用'}</span></div></header><div class="agent-thread" id="agent-thread"></div><form class="agent-composer" id="agent-form"><textarea name="message" id="agent-input" aria-label="描述症状或预约需求" placeholder="描述你的不适、持续时间，或告诉我你想预约什么科室…" maxlength="3000" required></textarea><div class="composer-bottom"><div class="flex wrap"><label class="check"><input type="checkbox" id="use-profile">读取本人基础档案</label><label class="check"><input type="checkbox" id="use-online" ${state.onlineConfigured?'':'disabled'}>发送到在线模型</label></div><button class="primary" type="submit">发送 ${icon('arrow')}</button></div><p class="small muted" id="agent-send-status" aria-live="polite"></p></form></section><aside class="agent-side stack"><section class="card"><h2><span class="step-number">1</span>就诊摘要</h2><p class="small muted">由你的描述整理，可复制给医生。</p><div class="summary-box" id="agent-summary">对话后，摘要会出现在这里。未提供的信息会保留为“待补充”。</div><button class="text-button section-gap" data-action="summary-download">${icon('download')} 导出摘要</button></section><section class="card" id="agent-booking"><h2><span class="step-number">2</span>辅助预约</h2><p class="small muted">助手查询医生，你确认预约。</p><div id="agent-doctors"></div></section><section class="card"><h2>使用说明</h2><p class="small muted">离线模式使用有限规则，不等同于大模型或临床分诊。在线模式需你自行配置兼容服务。</p><div class="notice">如有正在发生的胸痛、严重呼吸困难或意识异常，请直接联系急救或急诊，不要等待本系统预约。</div><div class="source-links"><a href="https://www.nhs.uk/symptoms/chest-pain/" target="_blank" rel="noreferrer">紧急征象参考 ↗</a></div></section></aside></div>`;
 paintAgentThread();paintAgentSide();
 $('#agent-form').addEventListener('submit',async event=>{
  event.preventDefault();const form=event.currentTarget;const input=$('#agent-input');const message=input.value.trim();if(!message)return;
  const button=$('[type=submit]',form);button.disabled=true;input.disabled=true;$('#agent-send-status').textContent=$('#use-online').checked?'在线模型正在整理，最长约 35 秒…':'正在整理描述、查询本机医生目录…';
  state.agentHistory.push({role:'user',text:message});paintAgentThread();input.value='';
  try{const result=await api('/api/agent/chat',{message,online:$('#use-online').checked,use_profile:$('#use-profile').checked});state.latest=result;state.agentHistory.push({role:'assistant',text:result.message,payload:result});if(state.route==='agent'){paintAgentThread();paintAgentSide();$('#agent-send-status').textContent=result.online_error?'在线模型未完成，已返回离线结果。':'已完成。预约需核对后单独确认。';}}
  catch(error){if(state.route==='agent'){$('#agent-send-status').textContent=error.message;input.value=message;}state.agentHistory.pop();paintAgentThread();}
  finally{button.disabled=false;input.disabled=false;if(input.isConnected)input.focus();}
 });
 $('#agent-input').addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='Enter')$('#agent-form').requestSubmit();});
}
function paintAgentThread(){
 const thread=$('#agent-thread');if(!thread)return;
 thread.innerHTML=state.agentHistory.length?state.agentHistory.map(h=>h.role==='user'?`<div class="message-meta">你</div><div class="chat-bubble self">${e(h.text)}</div>`:agentAnswer(h.payload,h.text)).join(''):`<div class="welcome"><div class="welcome-symbol">${icon('agent')}</div><div class="eyebrow">A LITTLE CLARITY, A LITTLE CARE</div><h2>今天，有什么想和我聊聊？</h2><p>我可以整理症状、准备就诊问题，<br>也可以帮你找到本机目录中的医生。</p><div class="suggestions"><button data-prompt="喉咙不舒服两天了，我应该补充哪些信息？">整理我的不适</button><button data-prompt="我想预约明天的眼科，帮我准备一下。">准备一次预约</button><button data-prompt="去看医生前，我需要带哪些资料？">就诊前准备</button></div></div>`;
 thread.scrollTop=thread.scrollHeight;
}
function agentAnswer(r,fallback){if(!r)return `<div class="chat-bubble">${e(fallback)}</div>`;return `<article class="agent-answer"><div class="message-meta">${icon('agent')} ${e(r.label)} ${r.urgent?badge('优先急诊','danger'):''}</div><div class="answer-text ${r.urgent?'error':''}">${e(r.message)}</div>${!r.urgent&&r.questions?.length?`<div class="section-gap">${r.questions.map(q=>`<div class="question">${e(q)}</div>`).join('')}</div>`:''}<details><summary>查看 ${r.trace.length} 个处理步骤</summary>${r.trace.map(t=>`<div class="trace-item"><span class="trace-check">✓</span><div><strong>${e(t.tool)} · ${e(t.status)}</strong><p>${e(t.detail)}</p></div></div>`).join('')}</details>${r.sources?.length?`<div class="source-links">${r.sources.map(s=>`<a href="${e(s.url)}" target="_blank" rel="noreferrer">${e(s.title)} ↗</a>`).join('')}</div>`:''}</article>`;}
function paintAgentSide(){
 if(!$('#agent-summary'))return;const r=state.latest;
 $('#agent-summary').textContent=r?.summary||'对话后，摘要会出现在这里。未提供的信息会保留为“待补充”。';
 $('#agent-doctors').innerHTML=!r?empty('描述需求后，查看医生匹配结果。'):r.urgent?'<div class="error">已停止普通预约建议，请优先联系急诊。</div>':state.user.role==='doctor'?'<p class="small muted">医生端可查看整理结果。预约操作请使用患者账号。</p>':`<p class="small muted">${r.department?'就诊方向提示：'+e(depLabel(r.department)):'信息不足，暂未指定科室。'}</p>${r.doctors.slice(0,3).map(d=>`<div class="doctor-card section-gap"><h3>${e(d.name)}</h3><p>${e(depLabel(d.department))}</p><button class="primary" data-action="agent-book" data-doctor="${d.id}">核对并预约</button></div>`).join('')}<button class="text-button section-gap" data-action="agent-book">手动选择其他医生 →</button>`;
}
function agentSettings(){
 modal(`<h2>在线模型设置</h2><p class="small muted">支持 Chat Completions 格式的兼容服务。远程地址使用 HTTPS；本机模型可以使用 http://127.0.0.1:端口/v1。无需在这里安装任何组件。</p><form id="agent-settings-form"><div class="error hidden" role="alert"></div><div class="stack">${field('API 基础地址（通常以 /v1 结尾）','endpoint','','url','required placeholder="https://你的服务商/v1" autocomplete="off"')}${field('模型名称','model','','text','required placeholder="填写服务商提供的模型名" autocomplete="off"')}${field('API Key（本机无密钥服务可留空）','key','','password','autocomplete="off"')}<div class="notice">仅保留在当前登录会话，不写入配置文件。保存后仍需在输入框下勾选“发送到在线模型”。该服务会收到当前描述、最近对话和本次摘要；不要发送不愿交给服务商的内容。</div><div class="flex"><button class="primary" type="submit">保存到当前会话</button><button class="secondary" type="button" data-action="agent-disconnect">清除在线配置</button></div></div></form>`);
 $('#agent-settings-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;try{await api('/api/agent/config',Object.fromEntries(new FormData(form)));state.onlineConfigured=true;$('#modal').close();toast('配置已保存。勾选在线发送后生效。');if(state.route==='agent'){const el=$('#use-online');el.disabled=false;$('#agent-mode').textContent='在线模型已配置';}}catch(error){showError(error,$('.error',form));}});
}
async function fileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('读取文件失败。'));reader.readAsDataURL(file);});}
async function renderChat(){
 state.contacts=await api('/api/contacts');if(state.route!=='chat')return;
 if(!state.contacts.some(c=>c.id===state.peer))state.peer=state.contacts[0]?.id||null;
 $('#content').innerHTML=heading('医患沟通','在本机账号之间发送消息与附件。另开一个浏览器隐私窗口可以登录另一个账号。')+`<section class="card chat-layout"><aside class="contacts"><input id="contact-search" placeholder="搜索联系人" aria-label="搜索联系人"><div id="contact-list"></div></aside><section class="messages-panel"><header class="messages-header" id="messages-header"></header><div class="messages-thread" id="messages-thread"></div><form class="messages-form" id="messages-form"><textarea id="message-input" name="text" maxlength="6000" placeholder="输入消息…" aria-label="消息内容"></textarea><div class="flex spread section-gap"><label class="file-label">附件（≤ 5 MB）<input type="file" id="message-file" aria-label="消息附件"></label><button class="primary" type="submit">发送</button></div><div class="small muted section-gap" id="message-status" aria-live="polite"></div></form></section></section>`;
 const paintContacts=()=>{const search=$('#contact-search').value.toLowerCase();$('#contact-list').innerHTML=state.contacts.filter(c=>(c.name+' '+c.username).toLowerCase().includes(search)).map(c=>`<button class="contact ${c.id===state.peer?'active':''}" data-peer="${c.id}">${avatar(c)}<div><p>${e(c.name)}</p><small>${e(c.username)}</small></div></button>`).join('')||empty('没有联系人。');$$('[data-peer]').forEach(b=>b.addEventListener('click',async()=>{state.peer=Number(b.dataset.peer);paintContacts();await pollMessages(true);}));};$('#contact-search').addEventListener('input',paintContacts);paintContacts();await pollMessages(true);
 state.poll=setInterval(()=>pollMessages(false),2500);
 $('#messages-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const button=$('[type=submit]',form);const file=$('#message-file').files[0];if(!state.peer)return toast('请先选择联系人。');button.disabled=true;try{const data={receiver:state.peer,text:$('#message-input').value};if(file){if(file.size>5*1024*1024)throw Error('附件不能超过 5 MB。');data.file=await fileBase64(file);data.filename=file.name;}await api('/api/messages/send',data);form.reset();$('#message-status').textContent='已发送';await pollMessages(true);}catch(error){$('#message-status').textContent=error.message;}finally{button.disabled=false;}});
}
async function pollMessages(force=false){
 if(state.route!=='chat'||!$('#messages-thread'))return;const peer=state.peer;const contact=state.contacts.find(c=>c.id===peer);$('#messages-header').textContent=contact?contact.name:'请选择联系人';if(!peer){$('#messages-thread').innerHTML=empty('暂无可沟通的联系人。');return;}
 try{const messages=await api('/api/messages?peer='+peer);if(state.route!=='chat'||state.peer!==peer)return;const thread=$('#messages-thread');const key=peer+':'+messages.map(m=>m.id).join(',');if(!force&&thread.dataset.key===key)return;const atBottom=thread.scrollHeight-thread.scrollTop-thread.clientHeight<50;thread.dataset.key=key;thread.innerHTML=messages.length?messages.map(m=>`<div class="message-meta">${m.sender===state.user.id?'你':e(contact.name)} · ${e(formatDate(m.created))}</div><div class="chat-bubble ${m.sender===state.user.id?'self':''}">${e(m.text)}${m.has_attachment?`<div><a href="/api/attachment/${m.id}" download>下载附件：${e(m.filename)}</a></div>`:''}</div>`).join(''):empty('还没有消息，开始沟通吧。');if(force||atBottom)thread.scrollTop=thread.scrollHeight;
 }catch(error){if(state.route==='chat'&&$('#message-status'))$('#message-status').textContent=error.message;}
}
function barChart(items){if(!items.length)return empty('暂无数据。');const max=Math.max(...items.map(x=>x.count),1);const height=items.length*42+15;return `<svg class="chart" viewBox="0 0 600 ${height}" role="img" aria-label="统计条形图">${items.map((r,i)=>`<text x="0" y="${i*42+23}" fill="#71817a" font-size="12">${e(String(r.label).slice(0,18))}</text><rect x="180" y="${i*42+7}" width="${Math.max(4,r.count/max*355)}" height="22" rx="4" fill="#8eb09a"/><text x="${190+r.count/max*355}" y="${i*42+23}" fill="#173530" font-size="12">${r.count}</text>`).join('')}</svg>`;}
async function renderStats(){const data=await api('/api/stats');if(state.route!=='stats')return;$('#content').innerHTML=heading('数据统计','只统计与你关联的患者和预约，不展示其他医生的诊疗数据。')+`<div class="grid2"><section class="card"><h2>患者治疗状态</h2>${barChart(data.status.map(x=>({...x,label:statusLabel(x.label)})))}</section><section class="card"><h2>预约日期分布</h2>${barChart(data.appointments)}</section><section class="card"><h2>已记录主诉</h2><p class="small muted">仅按记录文本聚合，不代表疾病发病率。</p>${barChart(data.symptoms)}</section></div>`;}
async function renderAbout(){
 const report=await api('/api/migration');if(state.route!=='about')return;
 $('#content').innerHTML=heading('关于 iCure','保留最初的关怀，让项目在 Windows 上继续运行。')+`<div class="grid2"><section class="card about-hero"><img src="/assets/hospital.jpg" alt="原项目医院图片"><h2 class="section-gap">iCure 智慧医疗管理系统</h2><p class="small muted">原项目团队：Ku Yee Siang、Xu Jian Fa、Guo Gui Ying、Tu Kai Nee、Bee Jun Rong。</p><p class="small muted">由原 Qt/C++ 项目迁移为 Python 标准库服务与本机网页。公开展示版仅生成虚构演示账号，不包含原数据库。</p><div class="activity"><h3>活动公告</h3><p class="small">原项目活动页尚未发布具体活动，新版保留此状态。</p></div></section><section class="stack"><div class="card"><h2>原始数据迁移</h2><div class="grid2"><div><div class="metric-value">${report.accounts}</div><small class="muted">原有账号</small></div><div><div class="metric-value">${report.appointments}</div><small class="muted">历史预约</small></div></div><p class="small muted section-gap">${report.doctors} 位医生 · ${report.patients} 位患者 · ${report.relations} 条医患关系</p>${report.notes.map(note=>`<p class="notice">${e(note)}</p>`).join('')}</div><div class="card"><h2>运行与数据</h2><p class="small muted">只监听 127.0.0.1，供这台电脑使用。关闭启动窗口会停止服务。搬到另一台电脑时需要 Python 3.10 或以上版本，不需要 Qt 和 pip 安装。</p><button class="secondary" data-action="export">导出我的数据</button></div></section></div>`;
}

document.addEventListener('click',async event=>{
 const route=event.target.closest('[data-route]');if(route){await go(route.dataset.route);return;}
 const prompt=event.target.closest('[data-prompt]');if(prompt){$('#agent-input').value=prompt.dataset.prompt;$('#agent-input').focus();return;}
 const button=event.target.closest('[data-action]');if(!button)return;
 const action=button.dataset.action;
 try{switch(action){
  case'login-tab':state.tab=button.dataset.tab;renderLogin();break;
  case'demo-login':button.disabled=true;try{await login({username:'demo_'+button.dataset.role,password:'icure2026'});}finally{button.disabled=false;}break;
  case'logout':await api('/api/logout',{});state.user=null;state.csrf='';state.latest=null;state.onlineConfigured=false;renderLogin();break;
  case'language':state.lang=state.lang==='zh'?'en':'zh';await renderShell();toast(state.lang==='en'?'Navigation switched to English. Clinical content stays in its original language.':'已切换中文导航。');break;
  case'retry':await renderRoute();break;
  case'close-modal':$('#modal').close();break;
  case'book-modal':await bookModal(button.dataset.doctor||'');break;
  case'cancel-appointment':if(confirm('确定取消这条预约吗？取消后保留记录。')){await api('/api/appointments/cancel',{id:Number(button.dataset.id)});toast('预约已取消。');await renderRoute();}break;
  case'eye-chart':modal('<h2>原项目视力自测图</h2><p class="small muted">图片尺寸和观看距离未经校准，仅供原项目演示，不能据此测定真实视力。</p><img src="/assets/eyetest.jpg" width="100%" alt="原项目视力图">');break;
  case'agent-settings':agentSettings();break;
  case'agent-disconnect':await api('/api/agent/config',{clear:true});state.onlineConfigured=false;$('#modal').close();if($('#use-online')){$('#use-online').checked=false;$('#use-online').disabled=true;$('#agent-mode').textContent='离线规则可用';}toast('在线配置已清除。');break;
  case'agent-clear':if(confirm('清空当前账号的助手对话记录？')){await api('/api/agent/clear',{});state.latest=null;await renderAgent();}break;
  case'agent-book':if(state.latest?.urgent)return toast('当前描述含紧急信号，请优先联系急诊。');await bookModal(button.dataset.doctor||'',state.latest);break;
  case'summary-download':if(!state.latest)return toast('先描述你的需求，生成一份摘要。');download('iCure-就诊摘要.txt','iCure 就诊摘要（本人核实后提供给医生）\n\n'+state.latest.summary+'\n\n'+state.latest.message);break;
  case'export':{const result=await api('/api/backup',{});download(result.filename,JSON.stringify(result.data,null,2),'application/json;charset=utf-8');toast('已导出当前账号可见的数据。');break;}
 }}catch(error){showError(error);}
});

(async()=>{try{const result=await api('/api/me');state.user=result.user;state.csrf=result.csrf;state.onlineConfigured=result.online_configured;await renderShell();}catch{renderLogin();}})();
